package com.wifirename.module

import android.content.ComponentName
import android.content.Context
import androidx.compose.ui.graphics.Color

data class TemplateIcon(
    val id: String,
    val nameRes: Int,
    val summaryRes: Int,
    val swatch: List<Color>,
    val bgRes: Int,
    val fgRes: Int,
)

data class ExtraIcon(
    val id: String,
    val nameRes: Int,
    val imageRes: Int,
)

/**
 * Single source for the in-app icon list. Resource names are generated by
 * `tools/generate_icons.py`; keep the ids in sync when adding a template there.
 */
object IconCatalog {

    val templates = listOf(
        TemplateIcon(
            id = "simple_default",
            nameRes = R.string.icon_tpl_default,
            summaryRes = R.string.icon_tpl_default_summary,
            swatch = listOf(Color(0xFF1C1670), Color(0xFF5A2D91)),
            bgRes = R.drawable.ic_caret_wave_bg_default,
            fgRes = R.drawable.ic_caret_wave_fg_default,
        ),
        TemplateIcon(
            id = "simple_white",
            nameRes = R.string.icon_tpl_white,
            summaryRes = R.string.icon_tpl_white_summary,
            swatch = listOf(Color(0xFFF2F2F7)),
            bgRes = R.drawable.ic_tpl_simple_white_bg,
            fgRes = R.drawable.ic_tpl_simple_white_fg,
        ),
        TemplateIcon(
            id = "simple_black",
            nameRes = R.string.icon_tpl_black,
            summaryRes = R.string.icon_tpl_black_summary,
            swatch = listOf(Color(0xFF0B0B0F)),
            bgRes = R.drawable.ic_tpl_simple_black_bg,
            fgRes = R.drawable.ic_tpl_simple_black_fg,
        ),
        TemplateIcon(
            id = "simple_blue",
            nameRes = R.string.icon_tpl_blue,
            summaryRes = R.string.icon_tpl_blue_summary,
            swatch = listOf(Color(0xFF1D4ED8)),
            bgRes = R.drawable.ic_tpl_simple_blue_bg,
            fgRes = R.drawable.ic_tpl_simple_blue_fg,
        ),
        TemplateIcon(
            id = "simple_green",
            nameRes = R.string.icon_tpl_green,
            summaryRes = R.string.icon_tpl_green_summary,
            swatch = listOf(Color(0xFF15803D)),
            bgRes = R.drawable.ic_tpl_simple_green_bg,
            fgRes = R.drawable.ic_tpl_simple_green_fg,
        ),
        TemplateIcon(
            id = "simple_orange",
            nameRes = R.string.icon_tpl_orange,
            summaryRes = R.string.icon_tpl_orange_summary,
            swatch = listOf(Color(0xFFEA580C)),
            bgRes = R.drawable.ic_tpl_simple_orange_bg,
            fgRes = R.drawable.ic_tpl_simple_orange_fg,
        ),
        TemplateIcon(
            id = "simple_pink",
            nameRes = R.string.icon_tpl_pink,
            summaryRes = R.string.icon_tpl_pink_summary,
            swatch = listOf(Color(0xFFC2185B)),
            bgRes = R.drawable.ic_tpl_simple_pink_bg,
            fgRes = R.drawable.ic_tpl_simple_pink_fg,
        ),
    )

    val extras = listOf(
        ExtraIcon(
            id = "anime_1",
            nameRes = R.string.icon_anime_1,
            imageRes = R.drawable.ic_extra_1,
        ),
        ExtraIcon(
            id = "anime_2",
            nameRes = R.string.icon_anime_2,
            imageRes = R.drawable.ic_extra_2,
        ),
        ExtraIcon(
            id = "anime_3",
            nameRes = R.string.icon_anime_3,
            imageRes = R.drawable.ic_extra_3,
        ),
    )

    val defaultId: String = templates.first().id

    val allIds: List<String>
        get() = templates.map { it.id } + extras.map { it.id }

    fun template(id: String): TemplateIcon? = templates.firstOrNull { it.id == id }

    fun extra(id: String): ExtraIcon? = extras.firstOrNull { it.id == id }

    fun isKnown(id: String): Boolean = template(id) != null || extra(id) != null

    fun labelRes(id: String): Int =
        template(id)?.nameRes ?: extra(id)?.nameRes ?: templates.first().nameRes

    fun aliasSuffix(id: String): String =
        "IconAlias" + id.split('_').joinToString("") { part ->
            part.replaceFirstChar { it.uppercaseChar() }
        }

    fun component(context: Context, id: String): ComponentName =
        ComponentName(
            context.packageName,
            "${context.packageName}.${aliasSuffix(id)}",
        )
}
